-- Source: sql/analysis/10_analytical_views.sql
{{ config(materialized='view') }}

SELECT
  k.retail_year,
  k.period,
  k.sales_lines,
  k.units_sold,
  k.transactions,
  k.gross_sales,
  k.discount_value,
  k.sales_revenue,
  k.returns_value,
  k.net_revenue,
  k.cogs,
  k.gross_margin,
  k.promo_sales_revenue,
  k.target_net_revenue,
  k.aov,
  k.upt,
  k.asp,
  k.gross_margin_pct,
  k.return_rate_value,
  k.promo_revenue_share,
  k.target_achievement_pct,
  a.inventory_cells,
  a.in_stock_cells,
  CAST(a.in_stock_cells AS DOUBLE) / NULLIF(CAST(a.inventory_cells AS DOUBLE), 0) AS stock_availability
FROM {{ ref('v_kpi_segment_period') }} AS k
LEFT JOIN (
  SELECT
    x.retail_year,
    x.period,
    SUM(x.cells) AS inventory_cells,
    SUM(x.in_stock) AS in_stock_cells
  FROM (
    SELECT
      w.retail_year,
      w.retail_half AS period,
      COUNT(*) AS cells,
      SUM(CAST(f.is_in_stock AS INT)) AS in_stock
    FROM {{ ref('fact_inventory') }} AS f
    JOIN {{ ref('dim_retail_week') }} AS w
      ON w.retail_week_key = f.retail_week_key
    GROUP BY
      w.retail_year,
      w.retail_half
    UNION ALL
    SELECT
      w.retail_year,
      N'FY',
      COUNT(*),
      SUM(CAST(f.is_in_stock AS INT))
    FROM {{ ref('fact_inventory') }} AS f
    JOIN {{ ref('dim_retail_week') }} AS w
      ON w.retail_week_key = f.retail_week_key
    GROUP BY
      w.retail_year
  ) AS x
  GROUP BY
    x.retail_year,
    x.period
) AS a
  ON a.retail_year = k.retail_year AND a.period = k.period
WHERE
  k.segment_type = N'Estate'
